  <script>
    const faqItems = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel relaxed and content, but purring can also be a self-soothing behavior when they are stressed, recovering, or asking for attention."
      },
      {
        question: "How much sleep does a cat need?",
        answer: "Most adult cats sleep between 12 and 16 hours a day. Kittens and older cats may sleep even longer, especially after play sessions or meals."
      },
      {
        question: "Why does my cat knead blankets or laps?",
        answer: "Kneading is a comfort behavior that starts in kittenhood. Adult cats often keep doing it when they feel safe, cozy, and bonded to the person or place around them."
      },
      {
        question: "How can I help an indoor cat stay active?",
        answer: "Rotate toys, offer climbing spots, add window views, and schedule short play sessions with wand toys. Small daily bursts of movement usually work better than one long session."
      },
      {
        question: "What is the best way to introduce a new cat at home?",
        answer: "Start with separate spaces, swap scents before face-to-face meetings, and make introductions gradual. Slow steps help both cats build familiarity without feeling cornered."
      }
    ];

    const escapeHtml = (value) => value
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");

    function Hero() {
      return `
        <header class="hero">
          <p class="hero__eyebrow">Cat care FAQ</p>
          <h1 class="hero__title">Everything curious cat people ask.</h1>
          <p class="hero__copy">
            A clean, quick guide to common questions about cat behavior, routines, and day-to-day care.
            Every answer starts collapsed so readers can open only what they need.
          </p>
          <ul class="hero__meta" aria-label="Highlights">
            <li>5 common questions</li>
            <li>Collapsed by default</li>
            <li>Keyboard-friendly disclosure pattern</li>
          </ul>
        </header>
      `;
    }

    function FAQItem(item, index) {
      const panelId = `faq-panel-${index + 1}`;
      const buttonId = `faq-button-${index + 1}`;

      return `
        <div class="example">
          <h3 class="example__heading">
            <button
              class="example__button"
              id="${buttonId}"
              type="button"
              aria-expanded="true"
              aria-controls="${panelId}"
            >
              <span>${escapeHtml(item.question)}</span>
              <span class="example__icon" aria-hidden="true">+</span>
            </button>
          </h3>
          <div class="details" id="${panelId}" aria-labelledby="${buttonId}">
            <p>${escapeHtml(item.answer)}</p>
          </div>
        </div>
      `;
    }

    function FAQSection(items) {
      return `
        <section class="faq-section" aria-labelledby="faq-title">
          <div class="faq-section__header">
            <p class="faq-section__label">FAQ</p>
            <h2 class="faq-section__title" id="faq-title">Popular questions about cats</h2>
            <p class="faq-section__copy">
              Expand any answer to learn more about how cats rest, communicate, and settle into a home.
            </p>
          </div>
          <div class="faq-list">
            ${items.map(FAQItem).join("")}
          </div>
        </section>
      `;
    }

    function Footer() {
      return `
        <footer class="footer">
          Made as a standalone FAQ experience with accessible disclosure controls.
        </footer>
      `;
    }

    function App() {
      return `
        <div class="page-shell">
          ${Hero()}
          <main id="maincontent" tabindex="-1">
            ${FAQSection(faqItems)}
          </main>
          ${Footer()}
        </div>
      `;
    }

    function setupDisclosures() {
      document.querySelectorAll(".example__button").forEach((button) => {
        const panelId = button.getAttribute("aria-controls");
        const panel = panelId ? document.getElementById(panelId) : null;

        if (!panel) {
          return;
        }

        const close = () => {
          button.setAttribute("aria-expanded", "false");
          panel.hidden = true;
        };

        const toggle = () => {
          const expanded = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!expanded));
          panel.hidden = expanded;
        };

        close();
        button.addEventListener("click", toggle);
        button.addEventListener("keydown", (event) => {
          if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
            event.preventDefault();
            close();
            button.focus();
          }
        });
      });
    }

    document.getElementById("app").innerHTML = App();
    setupDisclosures();
  </script>
